fig>();\n39: \n40:   const displayableAttributes = activeVisit?.attributes\n41:     ?.filter(\n42:       (attribute) =>\n43:         visitAttributeTypes?.find(({ uuid }) => attribute?.attributeType?.uuid === uuid)?.displayInThePatientBanner,\n44:     )\n45:     .map((attribute) => ({\n46:       attribute,\n47:       value: getAttributeValue(attribute?.attributeType, attribute?.value),\n48:     }))\n49:     .filter(({ value }) => value != null && value !== '');\n50: \n51:   if (!displayableAttributes?.length) {\n52:     return null;\n53:   }\n54: \n55:   return (\n56:     <div className={styles.tagsContainer}>\n57:       {displayableAttributes.map(({ attribute, value }) => (\n58:         <Tag key={attribute?.attributeType?.uuid} type=\"gray\">\n59:           {value}\n60:         </Tag>\n61:       ))}\n62:     </div>\n63:   );\n64: };\n65: \n66: export default VisitAttributeTags;\n67: \n\n(End of file - 67 lines total)\n</content>"}]}]},"parent_tool_use_id":null,"session_id":"5fd15beb-7552-494a-bb8c-eb44db65d173","uuid":"b4ab4dab-e487-4f04-ae7f-a667f0ecf46d","timestamp":"2026-10-19T17:00:48.872Z","tool_use_result":[{"type":"text","text":"<repo>github.com/openmrs/openmrs-esm-patient-chart</repo>\n<path>packages/esm-patient-chart-app/src/patient-banner-tags/visit-attribute-tags.extension.tsx</path>\n<url>undefined</url>\n<content>\n1: import React from 'react';\n2: import dayjs from 'dayjs';\n3: import { Tag } from '@carbon/react';\n4: import { formatDate, useConfig, useVisit } from '@openmrs/esm-framework';\n5: import { type ChartConfig } from '../config-schema';\n6: import styles from './visit-attribute-tags.scss';\n7: \n8: interface VisitAttributeTagsProps {\n9:   patientUuid: string;\n10: }\n11: \n12: const getAttributeValue = (attributeType, value) => {\n13:   switch (attributeType?.datatypeClassname) {\n14:     case 'org.openmrs.customdatatype.datatype.ConceptDatatype':\n15:       return value?.display;\n16:     case 'org.openmrs.customdatatype.datatype.FloatDatat