Perform visit operation...\n35:  *     await updateVisit(visitData);\n36:  *\n37:  *     // Invalidate only visit history table, not current visit components\n38:  *     invalidateVisitHistory(mutate, patientUuid);\n39:  *   };\n40:  * }\n41:  * ```\n42:  */\n43: export function invalidateVisitHistory(mutate: KeyedMutator<unknown>, patientUuid: string): void {\n44:   mutate((key) => {\n45:     if (typeof key === 'string' && key.includes(`${restBaseUrl}/visit?patient=${patientUuid}`)) {\n46:       // Current visit keys have includeInactive=false\n47:       const isCurrentVisitKey = key.includes('includeInactive=false');\n48: \n49:       // Visit history keys typically have pagination parameters or no includeInactive parameter\n50:       const hasHistoryParams = key.includes('limit=') || key.includes('startIndex=') || key.includes('totalCount=');\n51:       const hasNoIncludeInactive = !key.includes('includeInactive');\n52: \n53:       // Invalidate if it's clearly a history key OR if it doesn't have includeInactive=false\n54:       // This ensures we target visit history while preserving current visit cache\n55:       return !isCurrentVisitKey && (hasHistoryParams || hasNoIncludeInactive);\n56:     }\n57:     return false;\n58:   });\n59: }\n60: \n61: /**\n62:  * Invalidates visit-related encounter data for a specific patient.\n63:  *\n64:  * This function is useful when operations create or modify encounters within visits,\n65:  * requiring the encounter lists and related data to be refreshed.\n66:  *\n67:  * @param mutate - SWR mutate function from useSWRConfig()\n68:  * @param patientUuid - Patient UUID to target encounter data for\n69:  *\n70:  * @example\n71:  * ```typescript\n72:  * // After creating a visit note (which creates an encounter)\n73:  * invalidatePatientEncounters(mutate, patientUuid);\n74:  * ```\n75:  */\n76: export function invalidatePatientEncounters(mutate: KeyedMutator<unknown>, patientUuid: string): void {\n77:   mutate((key) => {\n78:     return (\n79:       typeof key === 'string' && key.includes(`${restBaseUrl}/encounter`) && key.includes(`patient=${patientUuid}`)\n80:     );\n81:   });\n82: }\n83: \n84: /**\n85:  * Invalidates only the current (active) visit cache for a specific patient.\n86:  *\n87:  * This refreshes components using useVisit without triggering the visit revalidation cascade.\n88:  *\n89:  * @param mutate - SWR mutate function from useSWRConfig()\n90:  * @param patientUuid - Patient UUID to target current visit data for\n91:  */\n92: export function invalidateCurrentVisit(mutate: KeyedMutator<unknown>, patientUuid: string): void {\n93:   mutate((key) => {\n94:     return (\n95:       typeof key === 'string' &&\n96:       key.includes(`${restBaseUrl}/visit?patient=${patientUuid}`) &&\n97:       key.includes('includeInactive=false')\n98:     );\n99:   });\n100: }\n\n(Showing lines 1-100 of 134. Use offset=101 to continue.)\n</content>"}]}]},"parent_tool_use_id":null,"session_id":"5fd15beb-7552-494a-bb8c-eb44db65d173","uuid":"9645f595-e2ff-4222-9a21-b70e5ba29623","timestamp":"2026-10-19T17:00:49.204Z","tool_use_result":[{"type":"text","text":"<repo>github.com/openmrs/openmrs-esm-patient-chart</repo>\n<path>packages/esm-patient-common-lib/src/visit/revalidation-utils.ts</path>\n<url>undefined</url>\n<content>\n1: import type { KeyedMutator } from 'swr';\n2: import { restBaseUrl } from '@openmrs/esm-framework';\n3: \n4: /**\n5:  * Invalidates visit history table data without triggering global visit revalidation cascade.\n6:  *\n7:  * This function provides surgical SWR cache invalidation for visit operations. It targets only\n8:  * the paginated visit data used by the visit history table, avoiding unnecessary revalidation\n9:  * of the 28+ components that use current visit data via the useVisit hook.\n10:  *\n11:  * The implementation uses URL pattern matching to discriminate between:\n12:  * - Current visit keys (includeInactive=false) - these are NOT invalidated\n13:  * - Visit histo